<div class="offices-list" style="margin-top:12px"><?php foreach (bl_rows(bl_field('branches', 'option')) as $branch): ?><div class="office"><div class="pin" aria-hidden="true"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 22s8-9 8-13a8 8 0 0 0-16 0c0 4 8 13 8 13z"/><circle cx="12" cy="9" r="3"/></svg></div><div><a href="<?php echo esc_url($branch['map_link'] ?? ''); ?>" target="_blank" rel="noopener noreferrer"><div class="office-city"><?php echo bl_text($branch['name'] ?? ''); ?></div><div class="office-address"><?php echo bl_text($branch['address'] ?? ''); ?></div></a><?php if (!empty($branch['phone'])): ?><a href="tel:<?php echo esc_attr(preg_replace('/[^+0-9]/', '', $branch['phone'])); ?>"><?php echo bl_text($branch['phone']); ?></a><?php endif; ?><?php if (!empty($branch['email'])): ?><a href="mailto:<?php echo esc_attr($branch['email']); ?>"><?php echo bl_text($branch['email']); ?></a><?php endif; ?></div></div><?php endforeach; ?></div>
